query:
{ assertions(where: {predicate: {eq: "HAS_FORMULATION_VERSION"}}, sort: [{recordedAt: ASC}]) {
 uid id status recordedAt recordedTo validFrom validFromPrecision validFromBasis validToBasis privacyClass
 subject { __typename ... on ProductVariant { uid } }
 object { __typename ... on FormulationVersion { uid } }
 supersedesConnection { edges { properties { supersessionKind recordedAt sourceRevisionEventUid } node { uid } } }
 evaluatedBy { adjudicationKind verdict reviewerType status recordedAt }
 supportedBy { selectorKind quoteHash normalizationVersion snapshot { contentHashBasis captureCompleteness retrievedAt source { canonicalUri sourceKind } } }
 generatedBy { activityKind methodVersion associatedWithAgents { agentKind } } } }
